// Isolated software keys only. Stdout is a private test pipe, never a receipt.
import {createServer} from 'node:http';import{readFileSync}from'node:fs';import{randomBytes}from'node:crypto';import{pathToFileURL}from'node:url';
const base=pathToFileURL(process.env.YNX_QA_CENTRAL_SOURCE+'/packages/wallet-auth/');
const load=path=>import(new URL(path,base));
const {ProductSessionGatewayNodeHost}=await load('src/product-session-gateway-node-host.js'),{createProductSessionRequest,signProductSessionApproval,signProductSessionChallenge}=await load('src/product-session-v2.js'),{createProductSessionProofV2}=await load('src/product-session-proof-v2.js'),{encodeProductSessionGatewayProofHeaderV2}=await load('src/product-session-gateway-client.js'),{canonicalJSON}=await load('src/canonical.js'),{httpBodyDigest}=await load('src/session-proof.js');
const {p256}=await load('node_modules/@noble/curves/nist.js');
const platform=process.env.YNX_QA_PLATFORM??'web';
const registry=JSON.parse(readFileSync(new URL('product-session-registry.json',base))),token=()=>randomBytes(32).toString('base64url'),device=new Uint8Array(32).fill(3),secret=Buffer.from(device).toString('base64url');
const host=new ProductSessionGatewayNodeHost(registry,{statePath:process.env.YNX_QA_STATE_PATH,now:()=>new Date(),tokenFactory:token,centralBrowser:true,centralBrowserEcosystem:true,businessRevalidation:true,centralBackend:{backendClients:[{clientId:'ynx-mail-v1-sso-v1',keyId:'qa',publicKey:process.env.YNX_QA_PUBLIC_KEY}],familySealKey:randomBytes(32)}}),server=createServer(host.handler());await new Promise(resolve=>server.listen(0,'127.0.0.1',resolve));const url=`http://127.0.0.1:${server.address().port}`;
async function call(path,body){const r=await fetch(url+path,{method:'POST',headers:{'content-type':'application/json','x-request-id':'req_'+token(),...(platform==='web'?{origin:'https://mail.ynxweb4.com'}:{})},body:canonicalJSON(body)});if(r.status!==200)throw Error('QA_APPROVAL_FAILED');return(await r.json()).result;}
const request=createProductSessionRequest(registry,{productId:'mail',platform,deviceId:token(),deviceKey:Buffer.from(p256.getPublicKey(device,true)).toString('base64url'),scopes:['mail:account'],purpose:'Read isolated QA Social account',nonce:token(),state:token()}),approval=signProductSessionApproval(registry,request,{accountSecret:'1'.padStart(64,'0'),scopes:request.scopes,expiresAt:request.expiresAt});
const challenge=await call('/v2/product-sessions/challenge',{request,approval}),session=await call('/v2/product-sessions/complete',{request,approval,completion:signProductSessionChallenge(challenge,secret)});
function proof(path,body){const now=new Date();return encodeProductSessionGatewayProofHeaderV2(createProductSessionProofV2(session,{method:'POST',path,bodyDigest:httpBodyDigest(canonicalJSON(body)),nonce:token(),issuedAt:now.toISOString(),expiresAt:new Date(+now+30000).toISOString()},secret));}
process.stdout.write(JSON.stringify({url,session,initial:proof('/v2/product-sessions/introspect',{requiredScopes:['mail:account']}),revoke:proof('/v2/product-sessions/revoke',{})})+'\n');
